pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial deposit amount and a second reentrancy-triggering amount
    function testFuzz_property(uint96 depositAmount) public {
        vm.assume(depositAmount > 0);
        // deploy attacker helper that will try to reenter on receive
        Attacker attacker = new Attacker(address(c));

        // fund attacker
        vm.deal(address(attacker), uint256(depositAmount));

        // attacker deposits depositAmount into c
        attacker.depositToC{value: uint256(depositAmount)}();

        // attacker calls withdrawAll, which will attempt to reenter during the external call
        // wrap call to observe if withdrawAll completes (for both contracts it should complete),
        // but we assert a postcondition on c: attacker's credit must be zero after withdrawal
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // single universal assertion: after withdrawAll returns, the attacker's recorded credit in C must be 0
        // This holds for the reference (it uses a reentrancy lock), but the mutant that zeroes credit before the external call
        // may allow an attacker to reenter and extract funds more than their credit, breaking the intended invariant
        assertTrue(ok && c.credit(address(attacker)) == 0);
    }
}

// Minimal attacker that re-enters C during receive to try to withdraw twice.
contract Attacker {
    C public target;
    bool public firstCallDone;

    constructor(address _target) {
        target = C(_target);
    }

    // deposit helper
    function depositToC() external payable {
        (bool success, ) = address(target).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(success);
    }

    // entry that calls withdrawAll on target
    function callWithdrawAll() external {
        (bool success, ) = address(target).call(abi.encodeWithSignature("withdrawAll()"));
        require(success);
    }

    // receive will attempt reentrancy once
    receive() external payable {
        if (!firstCallDone) {
            firstCallDone = true;
            // attempt to reenter withdrawAll
            // use low-level call to simulate caller performing another withdrawAll during the external call
            (bool success, ) = address(target).call(abi.encodeWithSignature("withdrawAll()"));
            // ignore success to allow behavior divergence between reference and mutant to surface
            success;
        }
    }
}

