    function testFuzz_property(uint256 depositAmount, uint256 attackerInitial) public {
        // keep values in reasonable range but wide
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerInitial = bound(attackerInitial, depositAmount, 10 ether);

        // deploy attacker helper that will try to re-enter on receive
        Attacker a = new Attacker(address(c));

        // fund attacker externally so it can deposit
        vm.deal(address(a), attackerInitial);

        // attacker deposits depositAmount into c via its fallback which forwards to deposit
        // we instruct attacker to perform the deposit
        a.performDeposit{value: depositAmount}();

        // check balances before withdraw
        uint256 before = address(c).balance;

        // now attempt withdrawAll as attacker; use try/catch to capture success
        bool ok;
        try a.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdrawAll completes on the reference, c.balance must have decreased by exactly depositAmount
        // (attacker may have triggered reentrancy but the reference contract's lock prevents extra draining)
        // We assert that the reference satisfies this for all inputs; the mutant will allow further drain for some inputs,
