// Minimal attacker helper that will deposit into C and then call withdrawAll; its receive tries to reenter once
contract Attacker {
    address payable immutable target;
    bool reentered;

    constructor(address _target) {
        target = payable(_target);
    }

    // receive will attempt to reenter by calling withdrawAll on target once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to call withdrawAll during the external callback
            // use low-level call to preserve behavior
            (bool s, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // ignore success; we're testing balance effects in the test
            s;
        }
    }

    // deposit into target
    function performDeposit() external payable {
        // forward to deposit
        (bool s, ) = target.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(s);
    }

    // trigger withdrawAll from this contract
    function triggerWithdraw() external {
        (bool s, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        require(s);
    }
