        AttackerA a = new AttackerA(c);

        // fund both attacker helper contract and the EOA that will deposit
        vm.deal(address(a), 0);
        vm.deal(attacker, depositAmount);

        // The EOA (attacker) will deposit into c but we make the deposit credited to the helper contract by using the helper's address as msg.sender
        // To do that, we have the EOA call helper which in turn forwards deposit call as the helper (so msg.sender is helper)
        // Deploy a proxy helper facilitator to forward a deposit from the fuzzed EOA into c under the helper's address
        DepositForwarder f = new DepositForwarder();
        // Fund forwarder so it can pay gas
        vm.deal(address(f), 1 wei);

        // Make the fuzzed EOA perform the deposit but via the forwarder calling c.deposit{value:...} from the helper contract address.
        // We instead have the helper a call deposit directly: set up attacker EOA to send ETH to helper, then helper will call c.deposit
        // Send ETH from the fuzzed EOA to helper
        vm.prank(attacker);
        (bool sent,) = address(a).call{value: depositAmount}("");
        require(sent);

        // Now helper has ETH. It will call c.deposit to credit itself
        a.depositToC{value: depositAmount}();

        // Sanity: helper's credit in c should now be depositAmount. We can only observe via attempting a withdraw and observing success/contract balance
        // Prepare to attempt withdrawAll from the helper which will re-enter during receive()

        // Call withdrawAll from the helper; this triggers reentrancy for the mutant but should be safe in reference
        bool ok;
        // use try/catch to capture any unexpected revert
        try a.doWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after withdrawAll returns (succeeds or not), the recorded credit for the helper (as observed by attempting another withdraw) is zero in the reference implementation for ALL inputs.
        // We observe this by calling withdrawAll again and seeing it returns (succeeds) with no funds withdrawn (i.e., no extra Ether available). To keep observation via public surface, we check that a second withdrawAll call does not transfer any ETH out (it will be a no-op but still succeed). We'll detect transfers by comparing address(c).balance change.

        // Capture contract balance before second withdraw
        uint256 before = address(c).balance;
        // Perform second withdrawAll via helper and observe whether contract balance decreases (meaning first withdraw didn't clear credit and there is double-withdrawable funds)
        try a.doWithdrawAll() {
            // succeeded
        } catch {
            // ignore revert: treat as success=false below
        }
        uint256 after = address(c).balance;

        // The invariant: after the first withdrawAll completes in the reference implementation, a subsequent withdrawAll by the same helper cannot withdraw any additional ETH, so contract balance must not decrease further (after >= before).
        // For the correct contract this holds for ALL inputs. The mutant that calls external before clearing credit can allow reentrancy and cause after < before for some inputs.
        assertTrue(after >= before);
